BEGIN;
INSERT INTO mission_bridge_permissions(key,description) VALUES('reentry.criminal_record.read','Read restricted criminal record details') ON CONFLICT DO NOTHING;
INSERT INTO mission_bridge_role_permissions(role_key,permission_key) VALUES('safeguarding_officer','reentry.criminal_record.read'),('professional_referral_partner','reentry.criminal_record.read'),('platform_admin','reentry.criminal_record.read') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS mission_bridge_reentry_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,owner_user_id TEXT NOT NULL,pseudonym TEXT NOT NULL,participant_type TEXT NOT NULL CHECK(participant_type IN('incarcerated_family','released_person')),criminal_record_encrypted TEXT NOT NULL DEFAULT '',access_class TEXT NOT NULL DEFAULT 'criminal_restricted',long_term_label TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(access_class='criminal_restricted'),CHECK(long_term_label IS NULL));
CREATE TABLE IF NOT EXISTS mission_bridge_reentry_family_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_reentry_profiles(id),repair_goal TEXT NOT NULL,child_support_plan JSONB NOT NULL DEFAULT '{}'::jsonb,boundaries JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_reentry_employment_plans(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_reentry_profiles(id),skills JSONB NOT NULL,training_steps JSONB NOT NULL,employment_resources JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS mission_bridge_reentry_service_navigation(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_reentry_profiles(id),service_type TEXT NOT NULL CHECK(service_type IN('identity_document','public_service','housing','employment','legal')),status TEXT NOT NULL DEFAULT 'needed',notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS mission_bridge_reentry_referrals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_reentry_profiles(id),referral_type TEXT NOT NULL CHECK(referral_type IN('addiction','debt','legal','housing','employment')),verified_provider_id UUID REFERENCES mission_bridge_referral_directory(id),status TEXT NOT NULL DEFAULT 'requested');
CREATE TABLE IF NOT EXISTS mission_bridge_reentry_peer_mentors(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,mentor_user_id TEXT NOT NULL,training_verified BOOLEAN NOT NULL DEFAULT FALSE,boundary_agreement BOOLEAN NOT NULL DEFAULT FALSE,capacity INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS mission_bridge_reintegration_steps(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_reentry_profiles(id),title TEXT NOT NULL,participant_goal BOOLEAN NOT NULL DEFAULT TRUE,status TEXT NOT NULL DEFAULT 'planned');
CREATE TABLE IF NOT EXISTS mission_bridge_reentry_faith_choices(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_reentry_profiles(id),faith_exploration_opt_in BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mission_bridge_reentry_story_consents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id TEXT NOT NULL,profile_id UUID NOT NULL REFERENCES mission_bridge_reentry_profiles(id),testimony_identity_exposure BOOLEAN NOT NULL DEFAULT FALSE,fundraising_identity_exposure BOOLEAN NOT NULL DEFAULT FALSE,CHECK(testimony_identity_exposure=FALSE),CHECK(fundraising_identity_exposure=FALSE));
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['mission_bridge_reentry_profiles','mission_bridge_reentry_family_plans','mission_bridge_reentry_employment_plans','mission_bridge_reentry_service_navigation','mission_bridge_reentry_referrals','mission_bridge_reentry_peer_mentors','mission_bridge_reintegration_steps','mission_bridge_reentry_faith_choices','mission_bridge_reentry_story_consents'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id=current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id=current_setting(''app.tenant_id'',true))',t);END LOOP;END $$;
COMMIT;
